import { IBaseHiking } from '@apps/Hiking/@types/hikingList.types';
import { IUser } from '@apps/Users/@services/users.service';

import { IWorkoutTarget } from '../@types/workoutsTargets.types';

export const getEmptyWorkoutTarget = (author: IUser, hiking?: IBaseHiking): IWorkoutTarget => {
  return {
    id: 0,
    name: '',
    is_public: false,
    description: '',
    date_start: new Date(),
    date_finish: new Date(Date.now() + 86400000 * 30),
    hiking: hiking ?? null,
    author,
    date_create: new Date(),
    date_update: null,

    type: null,

    distance: null,
    alt_ascent: null,
    alt_descent: null,
    speed_max: null,
    speed_min: null,
    speed_avg: null,
    hr_max: null,
    hr_min: null,
    hr_avg: null,
    time_moving: null,
  };
};
