import React, { FormEvent } from 'react';

import Trash from '@pohodnik/icons/svg/UI/Trash';

import {
  marWorkoutTargetToAddDTO,
  marWorkoutTargetToUpdateDTO,
} from '@apps/Workouts/@mappers/workoutsTargets.mapper';
import { getWorkoutTypes } from '@apps/Workouts/@services/workouts.service';
import {
  addWorkoutTarget,
  updateWorkoutTarget,
} from '@apps/Workouts/@services/workoutsTargets.service';
import { IWorkoutType } from '@apps/Workouts/@types/workouts.types';
import { IWorkoutTarget } from '@apps/Workouts/@types/workoutsTargets.types';
import PageLoader from '@components/PageLoader';
import { getInputDate } from '@helpers/dateHelper';
import { err, success } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput from '@ui-kit/Input';
import InputTypes from '@ui-kit/Input/InputTypes';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

interface IWorkoutTargetFormProps {
  data: IWorkoutTarget;
  onSave: (data: IWorkoutTarget) => void;
  onDelete: () => void;
  onCancel: () => void;
}

interface WorkoutTargetFormElements extends HTMLCollection {
  name: HTMLInputElement;
  description: HTMLInputElement;
  date_start: HTMLInputElement;
  date_finish: HTMLInputElement;
  workout_type: HTMLInputElement;
  distance: HTMLInputElement;
  time_moving: HTMLInputElement;
  alt_ascent: HTMLInputElement;
  alt_descent: HTMLInputElement;
  speed_min: HTMLInputElement;
  speed_avg: HTMLInputElement;
  speed_max: HTMLInputElement;
  hr_min: HTMLInputElement;
  hr_avg: HTMLInputElement;
  hr_max: HTMLInputElement;
  is_public: HTMLInputElement;
}

const WorkoutTargetForm: React.FC<IWorkoutTargetFormProps> = ({
  data,
  onSave,
  onDelete,
  onCancel,
}) => {
  const [modelData, setModelData] = React.useState<IWorkoutTarget>(data);
  const [types, setTypes] = React.useState<IWorkoutType[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);

  React.useEffect(() => {
    const init = async () => {
      try {
        const ts = await getWorkoutTypes();
        setTypes(ts);
      } catch (e) {
        err(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init().catch(err);
  }, []);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    const el = e.target as HTMLFormElement;
    const elements = el.elements as WorkoutTargetFormElements;

    const name = elements.name.value;
    const description = elements.description.value;
    const date_start = elements.date_start.value;
    const date_finish = elements.date_finish.value;
    const workout_type = elements.workout_type.value;
    const distance = elements.distance.valueAsNumber;
    const time_moving = elements.time_moving.valueAsNumber;
    const alt_ascent = elements.alt_ascent.valueAsNumber;
    const alt_descent = elements.alt_descent.valueAsNumber;
    const speed_min = elements.speed_min.valueAsNumber;
    const speed_avg = elements.speed_avg.valueAsNumber;
    const speed_max = elements.speed_max.valueAsNumber;
    const hr_min = elements.hr_min.valueAsNumber;
    const hr_avg = elements.hr_avg.valueAsNumber;
    const hr_max = elements.hr_max.valueAsNumber;
    const is_public = elements.is_public.checked;

    try {
      const model: IWorkoutTarget = {
        ...modelData,
        name,
        description,
        date_start: new Date(date_start!),
        date_finish: new Date(date_finish!),
        type: types.find((t) => t.id === +workout_type) ?? null,
        distance: Number.isFinite(distance) ? distance : null,
        alt_ascent: Number.isFinite(alt_ascent) ? alt_ascent : null,
        alt_descent: Number.isFinite(alt_descent) ? alt_descent : null,
        speed_max: Number.isFinite(speed_max) ? speed_max : null,
        speed_min: Number.isFinite(speed_min) ? speed_min : null,
        speed_avg: Number.isFinite(speed_avg) ? speed_avg : null,
        hr_max: Number.isFinite(hr_max) ? hr_max : null,
        hr_min: Number.isFinite(hr_min) ? hr_min : null,
        hr_avg: Number.isFinite(hr_avg) ? hr_avg : null,
        time_moving: Number.isFinite(time_moving) ? time_moving : null,
        is_public,
      };

      if (modelData.id > 0) {
        await updateWorkoutTarget(marWorkoutTargetToUpdateDTO(model));
        onSave({ ...model });
        success('Обновлено');
      } else {
        const { id } = await addWorkoutTarget(marWorkoutTargetToAddDTO(model));
        onSave({ ...model, id });
        setModelData({ ...model, id });
        success('Сохранено');
      }
    } catch (e1) {
      err(e1 as Error);
    }
  };

  if (isLoading) {
    return <PageLoader />;
  }

  return (
    <PohContainer className="p-3" as="form" onSubmit={handleSubmit}>
      <PohRow className="mb-3">
        <PohCol sm={6} className="mb-sm-3">
          <h4 className="mb-3">Основные параметры</h4>
          <PohInput
            label="Название"
            name="name"
            placeholder="Например: Пробежать сотку до отпуска"
            defaultValue={modelData.name}
            autoFocus
            required
            className="mb-3"
          />

          <PohInput
            label="Описание"
            name="description"
            placeholder="Например: Для спокойного выполнения надо бегать три раза в неделю по 5 км "
            type={InputTypes.textarea}
            defaultValue={modelData.description}
            required
            className="mb-3"
          />

          <PohRow className="mb-3">
            <PohCol sm={6}>
              <PohInput
                label="Дата начала тренировок"
                name="date_start"
                type={InputTypes.datetimeLocal}
                defaultValue={modelData.date_start ? getInputDate(modelData.date_start) : ''}
                required
              />
            </PohCol>
            <PohCol sm={6}>
              <PohInput
                label="Дата окончания тренировок"
                type={InputTypes.datetimeLocal}
                defaultValue={modelData.date_finish ? getInputDate(modelData.date_finish) : ''}
                name="date_finish"
                required
              />
            </PohCol>
          </PohRow>
          <PohRow className="mb-3">
            <PohCol sm={6}>
              <div className="form-group">
                <label htmlFor="workout_type">Тип тренировки</label>
                <select className="form-control" id="workout_type" name="workout_type">
                  {[{ id: 0, name: 'Все типы' }, ...types].map(({ id, name }) => (
                    <option
                      value={id.toString()}
                      key={id}
                      selected={id === (modelData.type?.id ?? 0)}
                    >
                      {name}
                    </option>
                  ))}
                </select>
              </div>
            </PohCol>
            <PohCol sm={6}>
              <div className="mt-4">
                <PohCheckbox
                  label="Публичная цель (Могут присоединяться другие)"
                  defaultChecked={modelData.is_public}
                  name="is_public"
                />
              </div>
            </PohCol>
          </PohRow>
        </PohCol>
        <PohCol className="border-start" sm={6}>
          <h4 className="mb-3">
            Цели показателей{' '}
            <small className="text-muted">
              <small>
                <small>(можно оставлять пустыми)</small>
              </small>
            </small>
          </h4>
          <PohRow className="mb-3">
            <PohCol sm={4}>
              <PohInput
                label="Σ Расстояние (м)"
                type={InputTypes.number}
                min={100}
                max={1000000}
                step={1}
                maxLength={7}
                defaultValue={modelData?.distance?.toString() || ''}
                name="distance"
                placeholder="любое"
              />
            </PohCol>
            <PohCol sm={4}>
              <PohInput
                label="Σ В движении (секунд)"
                type={InputTypes.number}
                min={10}
                max={10000}
                step={60}
                maxLength={6}
                defaultValue={modelData?.time_moving?.toString() || ''}
                name="time_moving"
                placeholder="любое"
              />
            </PohCol>
          </PohRow>
          <PohRow className="mb-3">
            <PohCol sm={4}>
              <PohInput
                label="Σ Набор высоты (м)"
                type={InputTypes.number}
                min={100}
                max={10000}
                step={1}
                maxLength={6}
                defaultValue={modelData?.alt_ascent?.toString() || ''}
                name="alt_ascent"
                placeholder="любой"
              />
            </PohCol>
            <PohCol sm={4}>
              <PohInput
                label="Σ Сброс высоты (м)"
                type={InputTypes.number}
                min={100}
                max={10000}
                step={1}
                maxLength={6}
                defaultValue={modelData?.alt_descent?.toString() || ''}
                name="alt_descent"
                placeholder="любой"
              />
            </PohCol>
          </PohRow>
          <PohRow className="mb-3">
            <PohCol sm={4}>
              <PohInput
                label="Скорость мин."
                type={InputTypes.number}
                min={1}
                max={200}
                step={1}
                maxLength={3}
                defaultValue={modelData?.speed_min?.toString() || ''}
                name="speed_min"
                placeholder="любая"
              />
            </PohCol>
            <PohCol sm={4}>
              <PohInput
                label="Скорость сред."
                type={InputTypes.number}
                min={1}
                max={200}
                step={1}
                maxLength={3}
                defaultValue={modelData?.speed_avg?.toString() || ''}
                name="speed_avg"
                placeholder="любая"
              />
            </PohCol>
            <PohCol sm={4}>
              <PohInput
                label="Скорость макс."
                type={InputTypes.number}
                min={1}
                max={200}
                step={1}
                maxLength={3}
                defaultValue={modelData?.speed_max?.toString() || ''}
                name="speed_max"
                placeholder="любая"
              />
            </PohCol>
          </PohRow>
          <PohRow className="mb-3">
            <PohCol sm={4}>
              <PohInput
                label="Пульс миним."
                type={InputTypes.number}
                min={30}
                max={250}
                step={1}
                maxLength={3}
                defaultValue={modelData?.hr_min?.toString() || ''}
                name="hr_min"
                placeholder="любой"
              />
            </PohCol>
            <PohCol sm={4}>
              <PohInput
                label="Пульс сред."
                type={InputTypes.number}
                min={30}
                max={250}
                step={1}
                maxLength={3}
                defaultValue={modelData?.hr_avg?.toString() || ''}
                name="hr_avg"
                placeholder="любой"
              />
            </PohCol>
            <PohCol sm={4}>
              <PohInput
                label="Пульс макс."
                type={InputTypes.number}
                min={30}
                max={250}
                step={1}
                maxLength={3}
                defaultValue={modelData?.hr_max?.toString() || ''}
                name="hr_max"
                placeholder="любой"
              />
            </PohCol>
          </PohRow>
        </PohCol>
      </PohRow>
      <footer className="mt-2 pt-2 border-top d-flex justify-content-between">
        <div>
          {modelData.id > 0 && (
            <PohButton
              onClick={onDelete}
              variant={ButtonVariant.Light}
              className="flex-shrink-0"
              title="удалить цель"
            >
              <Trash />
            </PohButton>
          )}
        </div>
        <div>
          <PohButton variant={ButtonVariant.Secondary} onClick={onCancel}>
            Отмена
          </PohButton>{' '}
          &nbsp;
          <PohButton variant={ButtonVariant.Primary} type="submit">
            {modelData.id > 0 ? 'Обновить' : 'Сохранить'}
          </PohButton>
        </div>
      </footer>
    </PohContainer>
  );
};

export default WorkoutTargetForm;
